:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] {
  --ui-toast-stack-gutter: 16px;
  --ui-toast-stack-peek: 8px;
  --ui-toast-stack-gap: 20px;
  --ui-toast-screen-space: calc(
    100dvh - max(8px, env(safe-area-inset-bottom)) - max(8px, env(safe-area-inset-top))
  );
  box-sizing: border-box;
  inset-inline-end: max(8px, env(safe-area-inset-right));
  inset-block-end: max(8px, env(safe-area-inset-bottom));
  width: min(412px, calc(100vw - 16px));
  max-height: var(--ui-toast-screen-space);
  padding: var(--ui-toast-stack-gutter);
