  position: relative;
  flex: none;
  height: calc(
    var(--ui-toast-head-height, var(--toast-frontmost-height, var(--ui-control-height-lg, 48px))) +
      var(--ui-toast-peek-space)
  );
  transition: height var(--ui-duration, 160ms) ease;
