:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast {
  --ui-toast-inset: clamp(12px, calc(var(--ui-space, 4px) * 4), 24px);
  --ui-toast-close-size: clamp(28px, var(--ui-control-height-sm, 32px), 32px);
  --ui-toast-stack-offset: calc(-1 * var(--toast-index, 0) * var(--ui-toast-stack-peek));
