  --ui-toast-stack-rise: 0px;
  z-index: calc(8 - var(--toast-index, 0));
  position: absolute;
  inset-inline: 0;
  inset-block-end: 0;
  min-height: 0;
  max-height: var(--ui-toast-max-card);
  padding: var(--ui-toast-inset);
  overflow: visible;
  transform: translateY(calc(var(--ui-toast-stack-offset) + var(--ui-toast-stack-rise)))
    scale(var(--ui-toast-stack-scale));
  transform-origin: top center;
  transition:
    transform var(--ui-duration, 160ms) ease,
    opacity var(--ui-duration, 160ms) ease;
