  background-color: color-mix(
    in srgb,
    var(--ui-pack-surface-bg, var(--ui-surface, #fff)),
    var(--ui-text, #171717) calc(var(--toast-index, 0) * 3%)
  );
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow:
    0 3px 10px color-mix(in srgb, #000 15%, transparent),
    0 1px 2px color-mix(in srgb, var(--ui-text, #171717) 16%, transparent);
