:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast-content {
  max-height: max(
    0px,
    calc(var(--ui-toast-max-card) - 2 * (var(--ui-toast-inset) + var(--ui-border-width, 1px)))
  );
