:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast-action:focus-visible {
  outline-offset: -2px;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast-close {
