  --ui-toast-stack-offset: calc(
    -1 * (var(--toast-offset-y, 0px) + var(--toast-index, 0) * var(--ui-toast-stack-gap))
  );
  --ui-toast-stack-scale: 1;
  height: auto;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack']:is([data-expanded], :focus-within) .ui-toast > * {
  opacity: 1;
  pointer-events: auto;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack']:is([data-expanded], :focus-within)
  .ui-toast
  .ui-toast-close {
  visibility: visible;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast:is([data-starting-style], [data-ending-style]) {
  --ui-toast-stack-rise: 12px;
  opacity: 0;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast[data-ending-style] {
  z-index: 0;
  pointer-events: none;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast[data-ending-style] > * {
  pointer-events: none;
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast[data-ending-style][data-swipe-direction='right'] {
  transform: translateX(calc(100% + 24px)) translateY(var(--ui-toast-stack-offset));
}

:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast[data-ending-style][data-swipe-direction='down'] {
  transform: translateY(calc(100% + 24px));
}

/* Keep every action reachable on touch devices without requiring a hover gesture. */
@media (any-pointer: coarse) {
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] {
    pointer-events: auto;
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast-items {
    height: var(--ui-toast-spread-height);
    pointer-events: auto;
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast {
    --ui-toast-close-size: 44px;
    --ui-toast-stack-offset: calc(
      -1 * (var(--toast-offset-y, 0px) + var(--toast-index, 0) * var(--ui-toast-stack-gap))
    );
    --ui-toast-stack-scale: 1;
    padding-inline-start: max(var(--ui-toast-inset), 40px);
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] .ui-toast:where(:has(.ui-toast-content[data-behind])) {
    height: auto;
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack']
    .ui-toast:where(:has(.ui-toast-content[data-behind]))
    > * {
    opacity: 1;
    pointer-events: auto;
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack']
    .ui-toast:where(:has(.ui-toast-content[data-behind]))
    .ui-toast-close {
    visibility: visible;
  }
}

/* Keep the empty live region mounted so the first announced item is detected. */
:where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'][data-empty] {
  padding: 0;
  pointer-events: none;
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-toast {
    --ui-toast-close-size: max(44px, var(--ui-control-height-sm, 32px));
  }
  :where([data-moru-registry]) .ui-toast-action {
    min-height: max(44px, var(--ui-control-height-sm, 32px));
  }
}

@media (max-width: 540px) {
  :where([data-moru-registry]) .ui-toast-viewport {
    inset-inline: 16px;
    width: auto;
  }
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] {
    inset-inline-start: max(0px, env(safe-area-inset-left));
    inset-inline-end: max(0px, env(safe-area-inset-right));
    width: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-toast,
  :where([data-moru-registry]) .ui-toast-viewport[data-layout='stack'] :is(.ui-toast, .ui-toast-content, .ui-toast-items) {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useCallback, useMemo, type CSSProperties, type ReactNode } from 'react'
import { Toast as BaseToast } from '@base-ui/react/toast'
import { CircleAlert, CircleCheck, Info, TriangleAlert, X } from 'lucide-react'
import type { SemanticTone } from './state'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './overlay-shared.css'
import './toast.css'

export interface ToastOptions {
  title: string
  description?: string
  tone?: SemanticTone
  action?: { label: string; onClick: () => void }
  /** Time in milliseconds. Zero keeps the notification until it is dismissed. */
  duration?: number
}

interface ToastData {
  tone: SemanticTone
}

export interface ToastProviderProps {
  children: ReactNode
  /** Present notifications separately, or overlap them until hovered or focused. */
  layout?: 'list' | 'stack'
  /** Maximum visible notifications, clamped between 1 and 5. Defaults to 3. */
  limit?: number
}

/** Wrap inside ThemeScope to carry the active design tokens into notifications. */
export function ToastProvider({ children, layout = 'list', limit = 3 }: ToastProviderProps) {
  const visibleLimit = Number.isFinite(limit) ? Math.min(5, Math.max(1, Math.trunc(limit))) : 3
  return (
    <BaseToast.Provider limit={visibleLimit} timeout={5000}>
      {children}
      <ToastViewport layout={layout} />
    </BaseToast.Provider>
  )
}

export function useToast() {
  const { add, close } = BaseToast.useToastManager<ToastData>()
  const toast = useCallback(
    ({ title, description, tone = 'info', action, duration = 5000 }: ToastOptions) => {
      let toastId = ''
      toastId = add({
        title,
        description,
        data: { tone },
        type: tone,
        priority: tone === 'danger' ? 'high' : 'low',
        timeout: Number.isFinite(duration) && duration >= 0 ? duration : 5000,
        actionProps: action
          ? {
              children: action.label,
              onClick: () => {
                action.onClick()
                close(toastId)
              },
            }
          : undefined,
      })
      return toastId
    },
    [add, close],
  )
  return useMemo(() => ({ toast, dismiss: close }), [toast, close])
}

const toneIcons = { success: CircleCheck, warning: TriangleAlert, info: Info, danger: CircleAlert }

function ToastViewport({ layout }: { layout: NonNullable<ToastProviderProps['layout']> }) {
  const { t } = useI18n()

  const { toasts } = BaseToast.useToastManager<ToastData>()
  const portalContainer = useThemePortalContainer()
  const visibleToasts =
    layout === 'stack'
      ? toasts.filter((toast) => !toast.limited && toast.transitionStatus !== 'ending')
      : []
  const stackStyle = {
    '--ui-toast-stack-depth': Math.max(0, visibleToasts.length - 1),
    '--ui-toast-height-total': `${visibleToasts.reduce((total, toast) => total + (toast.height ?? 0), 0)}px`,
    '--ui-toast-head-height': visibleToasts[0]?.height ? `${visibleToasts[0].height}px` : undefined,
  } as CSSProperties
  return (
    <OverlayPortal portal={BaseToast.Portal} kind="toast" container={portalContainer}>
      <BaseToast.Viewport
        className="ui-toast-viewport"
        data-layout={layout}
        data-empty={toasts.length === 0 || undefined}
        aria-label={t('알림 · F6 키로 이동')}
      >
        {toasts.length > 0 && (
          <div className="ui-toast-items" style={layout === 'stack' ? stackStyle : undefined}>
            {toasts.map((toast) => {
              const tone = toast.data?.tone ?? 'info'
              const Icon = toneIcons[tone]
              return (
                <BaseToast.Root key={toast.id} toast={toast} className="ui-toast" data-tone={tone}>
                  <BaseToast.Content
                    className="ui-toast-content"
                    data-base-ui-swipe-ignore={layout === 'stack' ? '' : undefined}
                  >
                    <Icon className="ui-toast-icon" size={18} aria-hidden="true" />
                    <div className="ui-toast-copy">
                      <BaseToast.Title className="ui-toast-title">{toast.title}</BaseToast.Title>
                      {toast.description && (
                        <BaseToast.Description className="ui-toast-description">
                          {toast.description}
                        </BaseToast.Description>
                      )}
                      {toast.actionProps && <BaseToast.Action className="ui-toast-action" />}
                    </div>
                  </BaseToast.Content>
                  <BaseToast.Close
                    className="ui-overlay-close ui-toast-close"
                    aria-label={t('알림 닫기')}
                    {...(layout === 'stack' ? { 'aria-hidden': false } : undefined)}
                  >
                    <X size={16} aria-hidden="true" />
                  </BaseToast.Close>
                </BaseToast.Root>
              )
            })}
          </div>
        )}
      </BaseToast.Viewport>
    </OverlayPortal>
  )
}
